package com.example.expensecalculator

/**
 * Data class representing an individual expense entry.
 *
 * @property id Unique identifier generated by SQLite (0 for newly created unsaved expenses).
 * @property title Description / title of the expense (e.g. "Grocery Shopping", "Metro Fare").
 * @property amount Numerical cost in INR, validated to be strictly greater than 0.
 * @property category One of the allowed categories: Food, Travel, Shopping, Bills, Other.
 * @property date ISO-8601 formatted date string ("yyyy-MM-dd") for deterministic chronological sorting.
 * @property createdAt Epoch timestamp in milliseconds for tie-breaking identical dates.
 */
data class Expense(
    val id: Long = 0,
    val title: String,
    val amount: Double,
    val category: String,
    val date: String,
    val createdAt: Long = System.currentTimeMillis()
) {
    companion object {
        const val CATEGORY_FOOD = "Food"
        const val CATEGORY_TRAVEL = "Travel"
        const val CATEGORY_SHOPPING = "Shopping"
        const val CATEGORY_BILLS = "Bills"
        const val CATEGORY_OTHER = "Other"

        val ALL_CATEGORIES = listOf(
            CATEGORY_FOOD,
            CATEGORY_TRAVEL,
            CATEGORY_SHOPPING,
            CATEGORY_BILLS,
            CATEGORY_OTHER
        )
    }
}
